629	func TestConcurrentFeedings(t *testing.T) {
630		s := openTestStore(t)
631		registerStandardRecipe(t, s, "recipe-1")
632		if _, err := s.CreateBatch("b1", "B1", "R1", "v1", 10); err != nil {
633			t.Fatal(err)
634		}
635		if _, err := s.StartBatch("s1", "B1"); err != nil {
636			t.Fatal(err)
637		}
638	
639		const n = 50
640		var wg sync.WaitGroup
641		errs := make(chan error, n)
